import { onMounted, onUnmounted } from 'vue'

const PREFERS_REDUCED = () =>
    window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches

export function track(name, params) {
    if (typeof window.gtag === 'function') window.gtag('event', name, params || {})
}

/**
 * Um único IntersectionObserver para a página inteira.
 * - [data-reveal] ganha a classe .is-visible ao entrar na viewport
 * - [data-count] anima o número de 0 até o valor final
 * Com prefers-reduced-motion tudo aparece direto, sem animar.
 */
export function useReveal() {
    let observer = null

    function countUp(el) {
        const target = Number(el.dataset.count)
        if (!Number.isFinite(target)) return
        if (PREFERS_REDUCED() || target === 0) {
            el.textContent = String(target)
            return
        }
        const duration = 1100
        const start = performance.now()
        function step(now) {
            const t = Math.min(1, (now - start) / duration)
            // easeOutCubic: acelera e freia no fim, como os contadores do app
            const eased = 1 - Math.pow(1 - t, 3)
            el.textContent = String(Math.round(target * eased))
            if (t < 1) requestAnimationFrame(step)
        }
        requestAnimationFrame(step)
    }

    onMounted(() => {
        const nodes = document.querySelectorAll('[data-reveal], [data-count]')

        if (!('IntersectionObserver' in window)) {
            nodes.forEach((el) => {
                el.classList.add('is-visible')
                if (el.dataset.count !== undefined) el.textContent = el.dataset.count
            })
            return
        }

        observer = new IntersectionObserver(
            (entries) => {
                entries.forEach((entry) => {
                    if (!entry.isIntersecting) return
                    const el = entry.target
                    el.classList.add('is-visible')
                    if (el.dataset.count !== undefined) countUp(el)
                    observer.unobserve(el)
                })
            },
            // Margem inferior pequena e fixa: uma porcentagem grande faz os últimos
            // blocos da página nunca cruzarem o observer e ficarem invisíveis.
            { rootMargin: '0px 0px -40px 0px', threshold: 0 }
        )

        nodes.forEach((el) => observer.observe(el))
    })

    onUnmounted(() => {
        if (observer) observer.disconnect()
    })
}

/** Marcos de rolagem no GA4 — sem isso não dá pra saber qual dobra perde o usuário. */
export function useScrollDepth() {
    const marks = [25, 50, 75, 100]
    let sent = []

    function onScroll() {
        const doc = document.documentElement
        const scrollable = doc.scrollHeight - window.innerHeight
        if (scrollable <= 0) return
        const pct = ((window.scrollY / scrollable) * 100)
        marks.forEach((m) => {
            if (pct >= m && !sent.includes(m)) {
                sent.push(m)
                track('scroll_depth', { page: 'foco-no-treino', percent: m })
            }
        })
    }

    onMounted(() => window.addEventListener('scroll', onScroll, { passive: true }))
    onUnmounted(() => window.removeEventListener('scroll', onScroll))
}
