/**
 * Confete em canvas, sem dependência externa.
 * As cores são exatamente as do tema do app (accentGreen/Blue/Purple/Pink/Gold/Orange),
 * então a celebração da landing é a mesma que o usuário vê ao concluir um treino.
 */
const COLORS = ['#00E676', '#3B82F6', '#8B5CF6', '#FF5C8A', '#FFC94D', '#FF8A3D']

export function useConfetti() {
    let raf = null

    function burst(canvas, count = 90) {
        if (!canvas) return
        if (window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches) return

        const dpr = window.devicePixelRatio || 1
        const w = canvas.offsetWidth
        const h = canvas.offsetHeight
        canvas.width = w * dpr
        canvas.height = h * dpr
        const ctx = canvas.getContext('2d')
        ctx.scale(dpr, dpr)

        const parts = Array.from({ length: count }, () => ({
            x: w / 2 + (Math.random() - 0.5) * w * 0.5,
            y: h * 0.32 + (Math.random() - 0.5) * 40,
            vx: (Math.random() - 0.5) * 7,
            vy: Math.random() * -9 - 3,
            size: Math.random() * 6 + 4,
            rot: Math.random() * Math.PI,
            vr: (Math.random() - 0.5) * 0.3,
            color: COLORS[Math.floor(Math.random() * COLORS.length)],
            life: 1
        }))

        if (raf) cancelAnimationFrame(raf)

        function frame() {
            ctx.clearRect(0, 0, w, h)
            let alive = false
            parts.forEach((p) => {
                if (p.life <= 0) return
                alive = true
                p.vy += 0.22          // gravidade
                p.vx *= 0.99          // arrasto
                p.x += p.vx
                p.y += p.vy
                p.rot += p.vr
                if (p.y > h * 0.75) p.life -= 0.03

                ctx.save()
                ctx.globalAlpha = Math.max(0, p.life)
                ctx.translate(p.x, p.y)
                ctx.rotate(p.rot)
                ctx.fillStyle = p.color
                ctx.fillRect(-p.size / 2, -p.size / 4, p.size, p.size / 2)
                ctx.restore()
            })
            raf = alive ? requestAnimationFrame(frame) : null
            if (!alive) ctx.clearRect(0, 0, w, h)
        }
        frame()
    }

    function stop() {
        if (raf) cancelAnimationFrame(raf)
        raf = null
    }

    return { burst, stop }
}
