<script setup>
import { onMounted, onUnmounted } from 'vue'
import LogoMark from '@/views/focoNoTreino/components/LogoMark.vue'
import PhoneMockup from '@/views/focoNoTreino/components/PhoneMockup.vue'
import StoreButtons from '@/views/focoNoTreino/components/StoreButtons.vue'
import SetSimulator from '@/views/focoNoTreino/components/SetSimulator.vue'
import content from '@/views/focoNoTreino/content/landing.js'
import { useReveal, useScrollDepth } from '@/views/focoNoTreino/composables/useReveal.js'

const c = content

// O estado inicial escondido do reveal só entra se houver IntersectionObserver
// para desfazê-lo. Sem isso, um JS quebrado deixaria a página em branco — o pior
// desfecho possível para uma landing que recebe tráfego pago.
const animate = typeof window !== 'undefined' && 'IntersectionObserver' in window

// Mapa explícito: o webpack resolve cada arquivo em build, sem require dinâmico.
const img = {
    home: require('@/assets/foco-no-treino/home.webp'),
    'treino-execucao': require('@/assets/foco-no-treino/treino-execucao.webp'),
    'treino-concluido': require('@/assets/foco-no-treino/treino-concluido.webp'),
    cardio: require('@/assets/foco-no-treino/cardio.webp'),
    'progresso-recordes': require('@/assets/foco-no-treino/progresso-recordes.webp'),
    'progresso-evolucao': require('@/assets/foco-no-treino/progresso-evolucao.webp'),
    'progresso-corpo': require('@/assets/foco-no-treino/progresso-corpo.webp'),
    'treinos-salvos': require('@/assets/foco-no-treino/treinos-salvos.webp'),
    'relatorio-pdf': require('@/assets/foco-no-treino/relatorio-pdf.webp')
}

const icons = {
    offline: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M5 12.55a11 11 0 0 1 14.08 0M1.42 9a16 16 0 0 1 21.16 0M8.53 16.11a6 6 0 0 1 6.95 0M12 20h.01M2 2l20 20"/></svg>',
    lock: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="11" width="18" height="11" rx="2"/><path d="M7 11V7a5 5 0 0 1 10 0v4"/></svg>',
    flame: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 2s4 4.5 4 8a4 4 0 0 1-8 0c0-1 .5-2 .5-2S6 11 6 14a6 6 0 0 0 12 0c0-5-6-12-6-12z"/></svg>'
}

function scrollTo(id) {
    const el = document.getElementById(id)
    if (el) el.scrollIntoView({ behavior: 'smooth', block: 'start' })
}

useReveal()
useScrollDepth()

// O index.html do portfólio traz título/idioma próprios; a rota tem os seus e
// devolve os originais ao sair. Mesmo padrão de PrivacyPolicyView.vue.
const originalTitle = document.title

onMounted(() => {
    document.title = c.meta.documentTitle
    document.documentElement.setAttribute('lang', c.meta.htmlLang)
    document.body.classList.add('fnt-body')
})

onUnmounted(() => {
    document.title = originalTitle
    document.body.classList.remove('fnt-body')
})
</script>

