<template>
    <div class="fnt-sim" :class="{ 'is-done': done }">
        <canvas ref="canvasEl" class="fnt-sim-confetti" aria-hidden="true"></canvas>

        <!-- Cabeçalho: espelha a barra superior da tela de execução do app -->
        <div class="fnt-sim-top">
            <div class="fnt-sim-top-txt">
                <small>Exercício 5/5</small>
                <strong>{{ completed + 17 }}/20 séries</strong>
            </div>
            <div class="fnt-sim-clock" :class="{ 'is-live': started }">
                <svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round">
                    <circle cx="12" cy="13" r="8"/><path d="M12 9v4l2.5 2M9 2h6"/>
                </svg>
                <span>{{ clock }}</span>
            </div>
        </div>

        <div class="fnt-sim-bar" role="progressbar" :aria-valuenow="pct" aria-valuemin="0" aria-valuemax="100">
            <span :style="{ width: pct + '%' }"></span>
        </div>

        <img
            class="fnt-sim-media"
            :src="exerciseImg"
            alt="Demonstração do exercício rosca martelo"
            loading="lazy"
            decoding="async" />

        <div class="fnt-sim-name">
            <div>
                <strong>Rosca martelo</strong>
                <small>Bíceps</small>
            </div>
            <span class="fnt-sim-xp-total">{{ xp }} XP</span>
        </div>

        <!-- Séries -->
        <div class="fnt-sim-head" aria-hidden="true">
            <span>#</span><span>REPS</span><span>CARGA</span><span></span>
        </div>

        <button
            v-for="set in sets"
            :key="set.n"
            type="button"
            class="fnt-sim-row"
            :class="{ 'is-done': set.n <= completed, 'is-current': set.n === completed + 1 && !done }"
            :disabled="set.n !== completed + 1"
            :aria-label="`Concluir série ${set.n}`"
            @click="completeSet">
            <span class="fnt-sim-n">{{ set.n }}</span>
            <span class="fnt-sim-v">{{ set.reps }}</span>
            <span class="fnt-sim-v">{{ set.load }} kg</span>
            <span class="fnt-sim-check">
                <svg v-if="set.n <= completed" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round">
                    <path d="M4 12.5l5 5L20 6.5"/>
                </svg>
            </span>
        </button>

        <!-- Descanso -->
        <transition name="fnt-fade">
            <div v-if="resting" class="fnt-sim-rest">
                <svg class="fnt-sim-rest-ico" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round">
                    <circle cx="12" cy="13" r="8"/><path d="M12 9v4l2.5 2M9 2h6"/>
                </svg>
                <strong>Descanso</strong>
                <span class="fnt-sim-rest-time">{{ restLabel }}</span>
                <button type="button" class="fnt-sim-ghost" @click.stop="restLeft += 15">+15s</button>
                <button type="button" class="fnt-sim-ghost" @click.stop="skipRest">Pular</button>
            </div>
        </transition>

        <!-- Resultado -->
        <transition name="fnt-fade">
            <div v-if="done" class="fnt-sim-result">
                <div class="fnt-sim-result-head">
                    <span class="fnt-sim-result-ico">
                        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round">
                            <path d="M4 12.5l5 5L20 6.5"/>
                        </svg>
                    </span>
                    <div>
                        <strong>Treino concluído!</strong>
                        <small>Mais um passo na sua evolução 💪</small>
                    </div>
                </div>
                <p class="fnt-sim-result-copy">
                    Isso foi só uma série. No app são treinos inteiros, cárdio, recordes e a sua evolução mês a mês.
                </p>
                <StoreButtons location="simulador" center />
                <button type="button" class="fnt-sim-reset" @click="reset">Refazer</button>
            </div>
        </transition>

        <!-- Ação principal -->
        <button
            v-if="!done"
            type="button"
            class="fnt-sim-cta"
            @click="completeSet">
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
                <path d="M4 12.5l5 5L20 6.5"/>
            </svg>
            Concluir série {{ completed + 1 }}
        </button>

        <p v-if="!started" class="fnt-sim-hint">{{ hint }}</p>

        <!-- XP flutuante -->
        <transition-group name="fnt-xp" tag="div" class="fnt-sim-floats" aria-hidden="true">
            <span v-for="f in floats" :key="f.id" class="fnt-sim-float">+{{ f.amount }} XP</span>
        </transition-group>
    </div>
</template>

<script setup>
import { ref, computed, onUnmounted } from 'vue'
import StoreButtons from '@/views/focoNoTreino/components/StoreButtons.vue'
import { useConfetti } from '@/views/focoNoTreino/composables/useConfetti.js'
import { track } from '@/views/focoNoTreino/composables/useReveal.js'

defineProps({
    hint: { type: String, default: 'Toque em “Concluir série” para começar' }
})

const exerciseImg = require('@/assets/foco-no-treino/exercicio-rosca-martelo.webp')

const REST_SECONDS = 90
const XP_PER_SET = 40

const sets = [
    { n: 1, reps: 10, load: 14 },
    { n: 2, reps: 10, load: 14 },
    { n: 3, reps: 10, load: 14 }
]

const canvasEl = ref(null)
const { burst, stop } = useConfetti()

const completed = ref(0)
const started = ref(false)
const resting = ref(false)
const restLeft = ref(REST_SECONDS)
const elapsed = ref(0)
const xp = ref(0)
const floats = ref([])

let restTimer = null
let clockTimer = null
let floatId = 0

const done = computed(() => completed.value === sets.length)
const pct = computed(() => Math.round(((completed.value + 17) / 20) * 100))

const fmt = (s) => `${String(Math.floor(s / 60)).padStart(2, '0')}:${String(s % 60).padStart(2, '0')}`
const clock = computed(() => fmt(elapsed.value))
const restLabel = computed(() => `${Math.floor(restLeft.value / 60)}:${String(restLeft.value % 60).padStart(2, '0')}`)

function pushFloat(amount) {
    const id = ++floatId
    floats.value.push({ id, amount })
    setTimeout(() => {
        floats.value = floats.value.filter((f) => f.id !== id)
    }, 1300)
}

function startClock() {
    if (clockTimer) return
    clockTimer = setInterval(() => { elapsed.value += 1 }, 1000)
}

function startRest() {
    resting.value = true
    restLeft.value = REST_SECONDS
    restTimer = setInterval(() => {
        restLeft.value -= 1
        if (restLeft.value <= 0) skipRest()
    }, 1000)
}

function skipRest() {
    clearInterval(restTimer)
    restTimer = null
    resting.value = false
}

function completeSet() {
    if (done.value) return
    // O descanso aqui é demonstração, não regra: quem quiser seguir direto segue.
    // Travar o botão nesta página só faria o visitante desistir do simulador.
    if (resting.value) skipRest()

    if (!started.value) {
        started.value = true
        startClock()
        track('simulator_start', { page: 'foco-no-treino' })
    }

    completed.value += 1
    xp.value += XP_PER_SET
    pushFloat(XP_PER_SET)

    if (done.value) {
        clearInterval(clockTimer)
        clockTimer = null
        burst(canvasEl.value)
        track('simulator_complete', { page: 'foco-no-treino', seconds: elapsed.value })
    } else {
        startRest()
    }
}

function reset() {
    skipRest()
    clearInterval(clockTimer)
    clockTimer = null
    stop()
    completed.value = 0
    started.value = false
    elapsed.value = 0
    xp.value = 0
    floats.value = []
}

onUnmounted(() => {
    clearInterval(restTimer)
    clearInterval(clockTimer)
    stop()
})
</script>

